INSERT OR REPLACE INTO ai_scores (accession_no, line_no, score, rating, comment, created_at) VALUES ('0001104659-26-104314', 3, 83, '强', '公司作为北美第二大固废及回收服务商，拥有由稀缺垃圾填埋场资产构筑的深厚护城河，定价能力极强且现金流极其稳定。行业具备典型的抗周期防御属性，虽然当前估值处于历史中高位，但高质量盈利与持续分红回购带来稳固基本面。技术面上，股价运行于50日及200日均线上方且接近52周高点，维持稳健上升趋势。', '2026-09-03 05:51:45.772679');
