INSERT OR REPLACE INTO ai_scores (accession_no, line_no, score, rating, comment, created_at) VALUES ('0002117905-26-000026', 3, 66, '中等', '作为美洲区域性贵金属及铜矿开采商，公司直接受益于黄金与铜价的强劲上行周期，近期盈利与现金流扩张显著。然而，中小型矿业公司业绩对大宗商品价格高度敏感，且面临地缘与矿山运营成本波动的风险。技术面上，近期股价自低位强劲反弹超180%并大幅站上均线，短期动能充沛但波动加剧。', '2026-09-03 05:51:45.775259');
