INSERT OR REPLACE INTO ai_scores (accession_no, line_no, score, rating, comment, created_at) VALUES ('0001193125-26-378510', 0, 78, '强', 'ITT在工业关键工程部件制造领域具备领先优势，业务覆盖航空航天、工业流体及交通运输等多元终端，抗周期分散能力突出。公司拥有充裕的资产负债表与稳健的营业利润率，长期内生增长和并购整合策略执行良好。技术面上，现价在50日及200日均线附近小幅整固，整体维持健康的均线多头支撑。', '2026-09-03 05:51:45.777248');
INSERT OR REPLACE INTO ai_scores (accession_no, line_no, score, rating, comment, created_at) VALUES ('0002021239-26-000006', 0, 62, '中等', '公司是全球温控冷链仓储物流的领军REIT，网络规模效应显著且终端客户黏性高。但作为重资产行业，高资本开支和相对较高的杠杆水平在利率偏高环境下对盈利构成压制，增长弹性受限。技术面上，股价近期承压跌破50日均线，近3个月回调约10%，短期处于探底整理阶段。', '2026-09-03 05:51:45.777623');
INSERT OR REPLACE INTO ai_scores (accession_no, line_no, score, rating, comment, created_at) VALUES ('0001104659-26-104314', 6, 83, '强', '公司作为北美第二大固废及回收服务商，拥有由稀缺垃圾填埋场资产构筑的深厚护城河，定价能力极强且现金流极其稳定。行业具备典型的抗周期防御属性，虽然当前估值处于历史中高位，但高质量盈利与持续分红回购带来稳固基本面。技术面上，股价运行于50日及200日均线上方且接近52周高点，维持稳健上升趋势。', '2026-09-03 05:51:45.777996');
INSERT OR REPLACE INTO ai_scores (accession_no, line_no, score, rating, comment, created_at) VALUES ('0001349628-26-000004', 0, 65, '中等', '公司作为电信与光纤基础设施外包工程核心承包商，长期受益于北美宽带扩建及BEAD等政策资本支出支持。但其业务具有明显的周期性与项目集中度风险，客户资本支出波动容易导致短期盈利大幅波动。技术面上，股价经历大幅回撤，距52周高点下跌超44%且远低于各条均线，短期下行趋势明显。', '2026-09-03 05:51:45.778380');
INSERT OR REPLACE INTO ai_scores (accession_no, line_no, score, rating, comment, created_at) VALUES ('0001437749-26-029371', 0, 85, '强', '公司拥有二叠纪盆地核心区域庞大的永久土地与矿权特许权使用费资产，享有极高的营业利润率与近乎无资本开支的商业模式。零负债资产负债表与强大的自由现金流回购机制赋予其无与伦比的基本面质量，尽管业绩受油气价格周期影响。技术面上，股价自高点回调32%并处于均线下方，短期动能偏弱但估值吸引力有所提升。', '2026-09-03 05:51:45.778752');
